sidebarCSS:
#root.root {--popup-bg: #F0E8DA;}
#root.root {--accent: #DBB4D3;}
#root.root {--status-notice: #90CDDE;}
#root.root {--status-active: #9BB0DE;}
#root.root {--status-err: #CF8282;}
#root.root {--status-ok: #9CCC96;}
#root.root {--frame-bg: #F8F4E9;}
#root.root {--tabs-normal-bg: #F0E8DA;}
#root.root {--tabs-activated-bg: #F0E8DA;}
#root.root {--toolbar-bg: #F0E8DA;}

#root.root {--tabs-activated-fg: #403732;}
#root.root {--tabs-normal-fg: #403732;}

#root.root {--nav-btn-fg: #6B564B;}
#root.root {--nav-btn-accent: #DBB4D3;}

#root.root {--general-border-radius: 8px;}

[data-color="blue"]      { --color: #9bb0de; } /* Blueberry */
[data-color="turquoise"] { --color: #90cdde; } /* Sky */
[data-color="green"]     { --color: #9ccc96; } /* Leaf */
[data-color="yellow"]    { --color: #e3cd7f; } /* Lemon */
[data-color="orange"]    { --color: #d4a266; } /* Orange */
[data-color="red"]       { --color: #cf8282; } /* Strawberry */
[data-color="pink"]      { --color: #edb7ca; } /* Pink */
[data-color="purple"]    { --color: #aa99d1; } /* Lavender */
[data-color="toolbar"]   { --color: #6b564b; } /* Subtext 2 */

/* Nav bar panel buttons */
.PanelButton[data-color] {
  --nav-btn-fg: var(--pc) !important;
}
.PanelButton[data-color] svg {
  fill: var(--pc) !important;
  color: var(--pc) !important;
}

/* Container color on tabs */
.Tab[data-color] {
  --tabs-indicator-bg: var(--pc) !important;
}
